// ============================================================
//  STREAMELEMENTS EVENTS
// ============================================================

window.addEventListener('onEventReceived', function (obj) {
    if (!obj.detail?.event) return;
    const listener = obj.detail.listener;
    const name = obj.detail.event.name || 'Quelqu\'un';

    if (listener === 'follower-latest') {
        document.getElementById('last-follower').textContent = name;
        showNotif({
            icon:  '🎣',
            title: 'Nouveau Follow !',
            name:  name,
            sub:   'vient de rejoindre l\'aquarium 🐟',
            isGold: false,
        });
    }

    if (listener === 'subscriber-latest') {
        document.getElementById('last-sub').textContent = name;
        showNotif({
            icon:  '⭐',
            title: 'Nouveau Sub !',
            name:  name,
            sub:   'merci du fond de l\'aquarium 🐠✨',
            isGold: true,
        });
        spawnGoldBubbles();
    }
});

// ============================================================
//  LOTTIE COINS
// ============================================================

function initLottieCorners() {
    const items = [
        // 4 coins — lottie 1 (étoile de mer), délais échelonnés
        { id: 'lottie-corner-tl', data: () => window.lottieOceanData,  startDelay: 0 },
        { id: 'lottie-corner-tr', data: () => window.lottieOceanData,  startDelay: 4000 },
        { id: 'lottie-corner-bl', data: () => window.lottieOceanData,  startDelay: 8000 },
        { id: 'lottie-corner-br', data: () => window.lottieOceanData,  startDelay: 12000 },
        // 2 décos bas — lottie 2 (animation différente)
        { id: 'lottie-bottom-l',  data: () => window.lottieOcean2Data, startDelay: 2000 },
        { id: 'lottie-bottom-r',  data: () => window.lottieOcean2Data, startDelay: 6000 },
    ];

    items.forEach(({ id, data, startDelay }) => {
        const el = document.getElementById(id);
        const animData = data();
        if (!el || !animData) return;

        const anim = bodymovin.loadAnimation({
            container: el,
            renderer: 'svg',
            loop: false,
            autoplay: false,
            animationData: animData,
        });

        function scheduleNext() {
            const delay = 12000 + Math.random() * 18000;
            setTimeout(() => {
                anim.goToAndPlay(0, true);
                anim.addEventListener('complete', function onDone() {
                    anim.removeEventListener('complete', onDone);
                    scheduleNext();
                });
            }, delay);
        }

        setTimeout(() => {
            anim.play();
            anim.addEventListener('complete', function onFirst() {
                anim.removeEventListener('complete', onFirst);
                scheduleNext();
            });
        }, startDelay);
    });
}

// ============================================================
//  INIT
// ============================================================

function init() {
    initAquarium();
    initLottieCorners();
}

document.addEventListener('DOMContentLoaded', init);
window.addEventListener('onWidgetLoad', init);


